CREATE TABLE semesters (id TEXT PRIMARY KEY, name TEXT NOT NULL, start_date TEXT NOT NULL, end_date TEXT NOT NULL CHECK(end_date >= start_date), status TEXT NOT NULL DEFAULT 'Active' CHECK(status IN ('Active','Archived')), storage_directory TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE UNIQUE INDEX one_active_semester ON semesters(status) WHERE status='Active';
CREATE TABLE courses (id TEXT PRIMARY KEY, semester_id TEXT NOT NULL REFERENCES semesters(id) ON DELETE CASCADE, code TEXT NOT NULL COLLATE NOCASE, name TEXT NOT NULL, professor TEXT NOT NULL DEFAULT '', section TEXT NOT NULL DEFAULT '', room TEXT NOT NULL DEFAULT '', credits REAL NOT NULL DEFAULT 3, color TEXT NOT NULL DEFAULT '#7770b5', folder_path TEXT NOT NULL UNIQUE, archived INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')), UNIQUE(semester_id,code));
CREATE INDEX courses_semester ON courses(semester_id,archived);
CREATE TABLE course_schedules (id TEXT PRIMARY KEY, course_id TEXT NOT NULL REFERENCES courses(id) ON DELETE CASCADE, day_of_week INTEGER NOT NULL CHECK(day_of_week BETWEEN 0 AND 6), start_time TEXT NOT NULL, end_time TEXT NOT NULL CHECK(end_time > start_time));
CREATE INDEX schedules_course ON course_schedules(course_id);
CREATE TABLE exams (id TEXT PRIMARY KEY, course_id TEXT NOT NULL REFERENCES courses(id) ON DELETE CASCADE, title TEXT NOT NULL, type TEXT NOT NULL DEFAULT 'Midterm', date TEXT NOT NULL, start_time TEXT NOT NULL DEFAULT '', end_time TEXT NOT NULL DEFAULT '', location TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', coverage TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX exams_due ON exams(date,course_id);
CREATE TABLE assignments (id TEXT PRIMARY KEY, course_id TEXT NOT NULL REFERENCES courses(id) ON DELETE CASCADE, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', assigned_date TEXT NOT NULL DEFAULT '', due_date TEXT NOT NULL, due_time TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'Not started' CHECK(status IN ('Not started','In progress','Completed','Submitted')), notes TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX assignments_due ON assignments(status,due_date,course_id);
CREATE TABLE tasks (id TEXT PRIMARY KEY, course_id TEXT REFERENCES courses(id) ON DELETE CASCADE, assignment_id TEXT REFERENCES assignments(id) ON DELETE SET NULL, exam_id TEXT REFERENCES exams(id) ON DELETE SET NULL, title TEXT NOT NULL, notes TEXT NOT NULL DEFAULT '', due_date TEXT NOT NULL DEFAULT '', due_time TEXT NOT NULL DEFAULT '', priority TEXT NOT NULL DEFAULT 'Normal' CHECK(priority IN ('Low','Normal','High')), completed INTEGER NOT NULL DEFAULT 0, completed_at TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX tasks_due ON tasks(completed,due_date,course_id);
CREATE TABLE calendar_events (id TEXT PRIMARY KEY, course_id TEXT REFERENCES courses(id) ON DELETE CASCADE, title TEXT NOT NULL, type TEXT NOT NULL DEFAULT 'Deadline', start_datetime TEXT NOT NULL, end_datetime TEXT NOT NULL DEFAULT '', all_day INTEGER NOT NULL DEFAULT 0, location TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX events_date ON calendar_events(start_datetime,course_id);
CREATE TABLE files (id TEXT PRIMARY KEY, course_id TEXT NOT NULL REFERENCES courses(id) ON DELETE CASCADE, semester_id TEXT NOT NULL REFERENCES semesters(id) ON DELETE CASCADE, filename TEXT NOT NULL, original_filename TEXT NOT NULL, category TEXT NOT NULL, absolute_path TEXT NOT NULL UNIQUE, extension TEXT NOT NULL, size INTEGER NOT NULL CHECK(size>=0), created_at TEXT NOT NULL, modified_at TEXT NOT NULL, added_at TEXT NOT NULL DEFAULT (datetime('now')), accessed_at TEXT, notes TEXT NOT NULL DEFAULT '');
CREATE INDEX files_category ON files(course_id,category,added_at DESC);
CREATE INDEX files_recent ON files(added_at DESC);
CREATE TABLE attachments (file_id TEXT NOT NULL REFERENCES files(id) ON DELETE CASCADE, entity_id TEXT NOT NULL, entity_type TEXT NOT NULL CHECK(entity_type IN ('exam','assignment')), PRIMARY KEY(file_id,entity_id,entity_type));
CREATE TABLE notifications (id TEXT PRIMARY KEY, type TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL, entity_id TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')), read INTEGER NOT NULL DEFAULT 0, priority TEXT NOT NULL DEFAULT 'Normal', delivered INTEGER NOT NULL DEFAULT 0);
CREATE INDEX notifications_unread ON notifications(read,created_at DESC);
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
INSERT INTO settings VALUES ('theme','system'),('notifications','false'),('file_behavior','copy');
CREATE TRIGGER exams_cleanup AFTER DELETE ON exams BEGIN DELETE FROM attachments WHERE entity_id=OLD.id AND entity_type='exam'; DELETE FROM notifications WHERE entity_id=OLD.id AND type='exam'; END;
CREATE TRIGGER assignments_cleanup AFTER DELETE ON assignments BEGIN DELETE FROM attachments WHERE entity_id=OLD.id AND entity_type='assignment'; DELETE FROM notifications WHERE entity_id=OLD.id AND type='assignment'; END;
